import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaUserCircle, FaLock, FaPlay, FaChartLine, FaSignOutAlt, FaHome } from 'react-icons/fa';
import { mockVideos } from '../../data/mockData';
import { useProgress } from '../../context/ProgressContext';
import '../../styles/StudentDashboard.css';
import '../../App.css';

const StudentDashboard = () => {
  const navigate = useNavigate();
  const { isUnlocked, completedVideos } = useProgress();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showProgress, setShowProgress] = useState(false);

  // Progress Calculations
  const totalVideos = mockVideos.length;
  // Use a customized calculation: IDs are [101, 102, 103]. 
  // We need to check how many of these are in completedVideos
  const completedCount = mockVideos.filter(v => completedVideos.includes(v.id)).length;
  const progressPercentage = Math.round((completedCount / totalVideos) * 100);

  // Mock Student Data State
  const [studentData, setStudentData] = useState({
    name: "Smyra Johnson",
    gender: "Female",
    email: "smyra.johnson@example.com"
  });

  const handleLogout = () => {
    navigate('/signup');
  };

  return (
    <div className="dashboard-container">
      {/* Profile Modal */}
      {showProfile && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2>Personal Profile</h2>
              <button onClick={() => setShowProfile(false)} className="close-btn">&times;</button>
            </div>
            <div className="profile-details">
              <div className="detail-item">
                <span className="detail-label">Name:</span>
                <span className="detail-value">{studentData.name}</span>
              </div>
              <div className="detail-item">
                <span className="detail-label">Gender:</span>
                <select
                  value={studentData.gender}
                  onChange={(e) => setStudentData({ ...studentData, gender: e.target.value })}
                  className="gender-select"
                >
                  <option value="Female">Female</option>
                  <option value="Male">Male</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div className="detail-item">
                <span className="detail-label">Email:</span>
                <span className="detail-value">{studentData.email}</span>
              </div>
            </div>
            <button onClick={() => setShowProfile(false)} className="modal-close-btn">Close</button>
          </div>
        </div>
      )}

      {/* Progress Tracker Modal */}
      {showProgress && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2>My Progress</h2>
              <button onClick={() => setShowProgress(false)} className="close-btn">&times;</button>
            </div>

            <div style={{ textAlign: 'center', padding: '20px 0' }}>
              <div className="progress-circle">
                <span className="progress-text">{progressPercentage}%</span>
              </div>
              <h3 style={{ marginTop: '20px', color: '#006D5B' }}>
                {completedCount} / {totalVideos} Modules Completed
              </h3>
              <div className="progress-bar-bg">
                <div className="progress-bar-fill" style={{ width: `${progressPercentage}%` }}></div>
              </div>
              <p style={{ color: '#666', marginTop: '15px' }}>
                {progressPercentage === 100
                  ? "Congratulations! You've completed all modules!"
                  : "Keep going! You're doing great."}
              </p>
            </div>

            <button onClick={() => setShowProgress(false)} className="modal-close-btn">Close</button>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <div
        className="sidebar"
        style={{ width: isSidebarOpen ? '250px' : '70px' }}
        onMouseEnter={() => setIsSidebarOpen(true)}
        onMouseLeave={() => setIsSidebarOpen(false)}
      >
        <button
          className="profile-button"
          onClick={() => setShowProfile(true)}
          title="View Profile"
        >
          <FaUserCircle size={40} color="#FFFDD0" />
          {isSidebarOpen && <span className="username">{studentData.name}</span>}
        </button>

        <div className="nav-items">
          <div className="nav-item">
            <FaHome size={24} className="nav-icon" />
            {isSidebarOpen && <span>Dashboard</span>}
          </div>
          <div className="nav-item" onClick={() => setShowProgress(true)}>
            <FaChartLine size={24} className="nav-icon" />
            {isSidebarOpen && <span>Progress Quiz</span>}
          </div>
        </div>

        <div className="logout-section" onClick={handleLogout}>
          <FaSignOutAlt size={24} className="nav-icon" />
          {isSidebarOpen && <span>Logout</span>}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="content-area">
        <div className="header">
          <h1 className="title">
            My Courses
          </h1>
        </div>

        <div className="grid">
          {mockVideos.map((video) => {
            const isLocked = !isUnlocked(video.id);
            return (
              <div key={video.id} className="card-custom">
                {/* Thumbnail */}
                <div className="thumbnail">
                  {isLocked ? (
                    <div className="text-center">
                      <FaLock size={30} style={{ marginBottom: '10px' }} />
                      <p>Locked</p>
                    </div>
                  ) : (
                    <Link to={`/video/${video.id}`} style={{ color: 'white' }}>
                      <FaPlay size={40} />
                    </Link>
                  )}
                </div>

                {/* Content */}
                <div className="card-content" style={{ padding: '20px' }}>
                  <h3 className="card-title">{video.title}</h3>
                  <p className="card-desc">{video.description}</p>

                  {isLocked ? (
                    <button className="disabled-btn" disabled>Complete Previous Task</button>
                  ) : (
                    <Link to={`/video/${video.id}`}>
                      <button className="start-btn">Start Module</button>
                    </Link>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;
